            "title": "Two thousand years to make ten centimetres of soil",
            "problem": "For the class exercise take the school figure that 500 years are needed to form 2.5 centimetres of topsoil. A field profile is 100 centimetres deep from the surface to the rock, and a farmer scrapes and burns a site. A candidate answers a 15-mark question on soil as a natural resource. Turn the formation rate into a sum. [15 marks]",
            "stepByStepSolution": [
              "Turns of the 500-year cycle needed for 10 centimetres: 10 divided by 2.5 = 4, so 4 times 500 = 2,000 years make the ten centimetres. [4 marks]",
              "Topsoil as a share of the whole profile: 10 divided by 100 times 100 = 10 per cent of the depth carries the fertility. [3 marks]",
              "Material below the topsoil line: 100 minus 10 = 90 centimetres of subsoil, weathered rock and stone. [2 marks]",
              "At the same rate the loss of 1 centimetre of topsoil to a scraped field is the loss of 500 years of work, and no dressing of fertiliser restores the soil's own texture. [2 marks]",
              "Soil is counted a renewable resource only on the geologist's clock, so 2 of the farmer's habits, burning and clean cultivation, spend it faster than it forms. [2 marks]",
              "Marks: 15 divided by 3 = 5 marks to each of rock, weathering and profile. [2 marks]"
            ],
            "keyTakeaway": "Ten centimetres of topsoil is 2,000 years of weathering, which is why one scraped field is a loss measured in centuries."
