    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Soil Physical Properties:\n  - Soil Texture: The relative proportion of different-sized mineral particles (Sand: 0.02–2.0 mm; Silt: 0.002–0.02 mm; Clay: < 0.002 mm). Permanent physical property!\n    * Sandy soil: High aeration, rapid drainage, low water and nutrient retention.\n    * Clayey soil: High water retention, sticky when wet, hard when dry, poor aeration, prone to waterlogging.\n    * Loamy soil: Ideal mixture of sand, silt, and clay with rich organic matter; optimal for most crops.\n  - Soil Structure: The arrangement of primary soil particles into aggregate clumps (peds). Types: Crumb (ideal for crops), granular, blocky, platy, prismatic.\n• Soil Chemical Properties:\n  - Soil Reaction (pH): Measure of hydrogen ion concentration. Scale: 1 to 14 (pH 7 is neutral; < 7 is acidic; > 7 is alkaline).\n    * Most crops thrive between pH 6.0 and 7.0.\n    * Acidic soils (common in high-rainfall southwestern Ghana) corrected by LIMING (adding agricultural limestone: CaCO3, CaO, or wood ash).\n  - Cation Exchange Capacity (CEC): Capacity of soil colloids to hold and exchange exchangeable cations (Ca2+, Mg2+, K+, NH4+).",
