"examples":       [
          {
            "id": "ex-agg-06-1",
            "title": "An NPK bag opened, and the nitrogen inside it",
            "problem": "A fertiliser bag labelled 15-15-15 weighs 50 kilograms and carries 15 per cent each of nitrogen, phosphate and potash. The farmer buys 8 bags for 3 acres needing 2 bags an acre, and weighs urea at 46 per cent nitrogen. A candidate answering a 20-mark question must name the macro and micro nutrients and work out what is actually applied. Open the bag. [20 marks]",
            "stepByStepSolution": [
              "Declared plant food in the compound: 15 plus 15 plus 15 = 45 per cent of the bag, the other 55 per cent being filler and carrier. [4 marks]",
              "Nitrogen in one bag: 50 times 15 divided by 100 = 7.5 kilograms. [3 marks]",
              "Nitrogen in 8 bags: 7.5 times 8 = 60 kilograms carried to the farm. [3 marks]",
              "Bags actually needed: 3 times 2 = 6, so 8 minus 6 = 2 bags are left on the store shelf. [4 marks]",
              "Urea at 46 per cent nitrogen delivers 100 times 46 divided by 100 = 46 kilograms of nitrogen in a 100-kilogram bag, three times the nitrogen of the compound in the same weight. [3 marks]",
              "The macro nutrients are 6 in the school list, nitrogen, phosphorus, potassium, calcium, magnesium and sulphur, and the micro nutrients are needed in traces, so the deficiency that yellowens the old leaves is not the one that bleaches the young. [3 marks]"
            ],
            "keyTakeaway": "A 15-15-15 bag is 45 per cent food and 7.5 kilograms of nitrogen, and the farmer's 8 bags were 2 more than the field could use."
          },
          {
            "id": "ex-agg-06-2",
            "title": "A compost heap built and a field dressed",
            "problem": "Compost is to be applied at 5 kilograms to a ridge on a plot of 400 ridges. The heap is built of 3 parts husk, 2 parts manure and 1 part soil and weighs 600 kilograms when made, and is turned 3 times in 90 days. NPK bags at 90 cedis each are the alternative. A candidate answers a 15-mark question on organic manures and inorganic fertilizers. Count the heap and the field. [15 marks]",
            "stepByStepSolution": [
              "Compost needed for the ridges: 5 times 400 = 2,000 kilograms, which is 2,000 divided by 1,000 = 2 tonnes. [3 marks]",
              "Parts in the heap: 3 plus 2 plus 1 = 6 parts make the whole, so the mixture is half husk by volume. [3 marks]",
              "Manure in the 600-kilogram heap: 600 times 2 divided by 6 = 200 kilograms. [2 marks]",
              "Days between turnings: 90 divided by 3 = 30 days, and the turning is what lets the heap heat evenly and rot without smelling. [3 marks]",
              "Cost of the chemical alternative at 6 bags: 6 times 90 = 540 cedis, and manure bought none of that but had to be carried and spread by hand. [2 marks]",
              "Marks: 15 divided by 3 = 5 marks to each of the nutrient, the source and the method of application. [2 marks]"
            ],
            "keyTakeaway": "Compost is a heap of six parts and two tonnes of work: 200 kilograms of manure in a 600-kilogram heap, turned every 30 days."
          }
        ],
