"examples":       [
          {
            "id": "ex-agg-07-1",
            "title": "Field capacity, wilting point and the days between waterings",
            "problem": "A soil holds 30 per cent water at field capacity and 12 per cent at the wilting point, with a root run of 60 centimetres. The crop draws 4 millimetres of water a day. In a comparative trial the furrow method applied 600 litres and the drip method 400 litres for the same yield. A candidate answers a 20-mark question on soil water, irrigation and drainage. Find the available water and the interval. [20 marks]",
            "stepByStepSolution": [
              "Water the crop can take: 30 minus 12 = 18 per cent of the soil, the band between the two constants. [4 marks]",
              "In the 60-centimetre root run that is 60 times 18 divided by 100 = 10.8 centimetres of available water. [3 marks]",
              "Ten point eight centimetres is 108 millimetres, and at 4 millimetres a day the store lasts 108 divided by 4 = 27 days before the crop begins to wilt. [4 marks]",
              "Water saved by drip against furrow: 600 minus 400 = 200 litres, which is 200 divided by 600 times 100 = 33.3 per cent less water for the same crop. [3 marks]",
              "Soil water is taught in 3 forms, gravitational water that drains away, capillary water that the roots use, and hygroscopic water held too fast for the plant, so 3 states name what the soil keeps and what it loses. [3 marks]",
              "Marks: 20 divided by 4 = 5 marks to each of the forms of water, the two constants, the choice of system and the need for drainage. [3 marks]"
            ],
            "keyTakeaway": "Irrigation timing is a subtraction and a division: 18 per cent available water in 60 centimetres gives 27 days of drought before the crop asks."
          },
          {
            "id": "ex-agg-07-2",
            "title": "A tank of ten thousand litres and the beds it can water",
            "problem": "A storage tank holds 10,000 litres, and each nursery bed takes 25 litres. One hundred beds can be watered in an hour, and 20 per cent of the draw-off is lost on seepage from the channel. A candidate answers a 15-mark question on irrigation practice. Work out the coverage, the clock and the loss. [15 marks]",
            "stepByStepSolution": [
              "Beds the tank will serve: 10,000 divided by 25 = 400 beds. [3 marks]",
              "Hours needed at 100 beds an hour: 400 divided by 100 = 4 hours of watering. [3 marks]",
              "Seepage loss: 10,000 times 20 divided by 100 = 2,000 litres never reach the bed. [2 marks]",
              "Water that reaches the crop: 10,000 minus 2,000 = 8,000 litres, so 8,000 divided by 25 = 320 beds are truly watered. [3 marks]",
              "Two signs of overwatering are a yellowed leaf and a checked root run, while the sign of underwatering is a midday droop that recovers by evening, and the farmer reads the leaf before opening the valve. [2 marks]",
              "Marks: 15 divided by 3 = 5 marks to each of supply, application and loss. [2 marks]"
            ],
            "keyTakeaway": "A full tank is not a full field: 2,000 litres lost on the channel leaves 320 beds watered instead of 400."
          }
        ],
