              "Cost of the posts: 200 times 15 = 3,000 cedis of timber before the wire is bought. [3 marks]",
              "The plan places 3 zones, the dwelling, the livestock yard and the store, and the prevailing wind decides which of the 3 lies upwind of the others. [3 marks]",
