            "title": "Farm calls, field schools and the five gates of adoption",
            "problem": "An extension officer visits 5 farms a day over a 20-day month, and a farmer field school of 25 members meets 8 times in the season with only half the members present each time. Extension methods are taught in 3 classes and the adoption process in 5 stages. A candidate answers a 20-mark question on extension teaching methods and rural development. Count the contacts. [20 marks]",
            "stepByStepSolution": [
              "Farm calls in the month: 5 times 20 = 100 visits, so 100 families were seen by 1 officer. [4 marks]",
              "Attendances possible at the field school: 25 times 8 = 200 seats, and with half attending, 200 divided by 2 = 100 attendances were made. [3 marks]",
              "Seats left empty at the school: 200 minus 100 = 100, so the method reached the group only on alternate meetings. [3 marks]",
              "Teaching methods are 3 in class, the individual contact, the group meeting and the mass medium, and each answers a different stage of the farmer's question. [4 marks]",
              "The adoption process runs through 5 stages, knowledge of the innovation, attitude toward it, the decision, the trial use and its continuance, so 1 improved variety must pass 5 gates before it becomes the village practice. [3 marks]",
              "Mass methods carry the same recommendation through 2 channels, radio and the poster, and neither answers the farmer's own field, which is why the visit and the school stand beside them. [3 marks]"
            ],
            "keyTakeaway": "Extension is counted in contacts: 100 farm calls, 100 attendances of 200 seats, and 5 gates between a leaflet and a practice."
