              "By the second year the adopters stood at 60 plus 40 = 100 farmers, which is 100 divided by 200 times 100 = 50 per cent of the district. [4 marks]",
              "The refusing remnant: 20 divided by 200 times 100 = 10 per cent, the laggards the extension worker is taught to leave to the second generation. [2 marks]",
              "The demonstration plot against the working plot: 0.5 divided by 1.5 times 100 = 33.3 per cent of the farmer's own land, small enough to be watched and copied. [2 marks]",
