    "isFreeTrial": true,
    "isVip": false,
    "keyNotes": "• Crop Classification Systems:\n  - By Life Cycle:\n    * Annuals: Complete life cycle within one single season or year (e.g. maize, rice, cowpea, tomato).\n    * Biennials: Require two growing seasons to complete life cycle (vegetative growth in year 1; flowering and seed production in year 2, e.g. carrot, cabbage, onion).\n    * Perennials: Live and produce crops for many years (> 2 years, e.g. cocoa, oil palm, mango, citrus).\n  - By Commercial / Economic Use:\n    * Cereals / Grains (carbohydrates): Maize, rice, sorghum, millet.\n    * Legumes / Pulses (protein): Cowpea, groundnut, soybean.\n    * Root & Tuber Crops (starch): Cassava, yam, cocoyam, sweet potato.\n    * Beverage & Stimulant Crops: Cocoa, coffee, tea.\n    * Fiber Crops: Cotton, jute, sisal.\n• Plant Morphology:\n  - Root Systems: Taproot system (dicotyledons) vs. Fibrous root system (monocotyledons). Functions: Anchorage, water/nutrient absorption, storage.\n  - Shoot System: Stem (transport, support), leaves (photosynthesis, transpiration via stomata), flowers (sexual reproduction).",
