              "The perennial holds the ground 20 times 12 = 240 months against the annual's 4 months of the same hectare. [3 marks]",
              "Share of that standing time used by the annual: 4 divided by 240 times 100 = 1.7 per cent. [3 marks]",
              "Economic classes run to 5 in the syllabus list, cereals for grain, legumes for seed and soil, root and tuber crops for starch, cash crops for sale, and vegetables and spices for the kitchen garden, so one crop may stand in 2 classes at once. [3 marks]",
              "The plant is described in 2 systems, root and shoot, and the tap root of a cowpea answers the fibrous root of a maize plant, so 2 root plans serve 2 ways of feeding. [3 marks]",
