            "stepByStepSolution": [
              "Germination of the lot: 85 divided by 100 times 100 = 85 per cent. [3 marks]",
              "Seeds sown: 5 times 3,000 = 15,000 grains on the hectare. [3 marks]",
              "Plants to be expected from that lot: 15,000 times 85 divided by 100 = 12,750 stands. [3 marks]",
              "Short of the target stand: 26,667 minus 12,750 = 13,917 plants, so the field will be thin unless it is retrenched at thinning or resown. [2 marks]",
              "A fine tilth decides whether the 12,750 that rise will hold, and clods leave the seed shallow and the roots hungry. [2 marks]",
              "Marks: 15 divided by 3 = 5 marks to each of site selection, spacing and seed rate. [2 marks]"
            ],
            "keyTakeaway": "The seed box and the test tube must agree: 15,000 grains at 85 per cent cannot fill a stand of 26,667."
