"examples":       [
          {
            "id": "ex-crp-03-1",
            "title": "Four hundred ridges from fifty mother stems",
            "problem": "Cassava is planted from stem stakes, and the class counts five asexual methods, cuttings, layering, budding, grafting and tissue culture, against the sexual method of seed. A plot of 400 ridges takes 1 stake to a ridge, and each mother stem cut from the hedge yields 8 stakes, of which 10 stems are kept back for the next season. A candidate answers a 20-mark question on propagation. Work the planting material. [20 marks]",
            "stepByStepSolution": [
              "The syllabus knows 2 ways of propagating crops, by seed in the sexual method and by the plant part in the asexual, so 1 class divides the whole of crop increase. [3 marks]",
              "Asexual routes are 5, the cutting, the layer, the bud, the graft and the cultured tissue, and each of the first four keeps the parent's characters unchanged. [4 marks]",
              "Stake length is given at 20 to 30 centimetres, so the span of the class is 30 minus 20 = 10 centimetres of stored food in the planting material. [3 marks]",
              "Stems cut for the plot: 400 stakes divided by 8 stakes to a stem = 50 mother stems. [4 marks]",
              "Stems that actually went to the planting: 50 minus 10 = 40, the other 10 held back to carry next season. [3 marks]",
              "Grafting joins a scion to a rootstock to make 1 tree out of 2 parents, while budding sets 1 bud rather than a length of bark, so both give the fruit without the seedling's uncertainty. [3 marks]"
            ],
            "keyTakeaway": "Vegetative propagation is a garden ledger: 400 ridges eat 50 stems, and the wise farmer cuts 40 and keeps 10."
          },
          {
            "id": "ex-crp-03-2",
            "title": "The seed that would not rise",
            "problem": "Germination is taught to require water, oxygen and a suitable temperature, with light needed by some seeds. A seed bed at 25 degrees rose in 5 days while a cold bed at 15 degrees took 10 days. Of 40 seeds of a dormant lot, only 20 per cent germinated, and dormancy is broken by scarification or stratification. A candidate answers a 15-mark question on germination physiology. Count the seeds and the days. [15 marks]",
            "stepByStepSolution": [
              "Conditions always required for germination are 3, water, oxygen and a suitable temperature, with light required by some species and not by others. [3 marks]",
              "Extra days taken by the cold bed: 10 minus 5 = 5 days lost to the lower temperature. [3 marks]",
              "Season time spent by the two sowings together: 5 plus 10 = 15 days of the planting window. [2 marks]",
              "Seeds that rose from the dormant lot: 40 times 20 divided by 100 = 8 seeds, so 40 minus 8 = 32 seeds lay still in the dish. [3 marks]",
              "Dormancy is answered by 2 treatments, scarification that wounds or softens the coat and stratification that chills the seed through a season, so 2 causes of stillness need 2 remedies. [2 marks]",
              "Marks: 15 divided by 3 = 5 marks to each of the sexual method, the asexual method and the breaking of dormancy. [2 marks]"
            ],
            "keyTakeaway": "Germination is a count of the risen, not the sown: 8 out of 40 seeds, and 5 cold days paid for the wrong temperature."
          }
        ],
