            "problem": "Cowpea is sown at 25 kilograms of seed to the hectare, counted at 8 seeds to the gram, and 90 per cent of the seed rises. The early class matures between 60 and 75 days. Two hectares gave 1,200 kilograms of pods, and an inoculated plot is reported to yield 30 per cent more. A candidate answering a 20-mark question on grain legumes must explain biological nitrogen fixation and the husbandry. Count the stand and the gain. [20 marks]",
