              "The early class runs from 60 to 75 days, so the span of earliness is 75 minus 60 = 15 days of the season. [3 marks]",
              "Seeds in the sowing: 25 kilograms is 25,000 grams, so 25,000 times 8 = 200,000 seeds to the hectare. [4 marks]",
              "Plants expected at 90 per cent: 200,000 times 90 divided by 100 = 180,000 stands. [3 marks]",
              "Yield rate on the field: 1,200 divided by 2 = 600 kilograms to the hectare. [3 marks]",
              "Gain from inoculation at 30 per cent: 600 times 30 divided by 100 = 180 kilograms more from the treated ground. [4 marks]",
              "Rhizobium lives in the root nodules and draws nitrogen from the air for the plant, so the legume feeds the soil it grows in while the cereal only takes from it. [3 marks]"
