    "keyNotes": "• Cassava Husbandry (Manihot esculenta):\n  - Drought-tolerant food security crop; propagated by mature stem cuttings (20–25 cm long with 4–6 nodes).\n  - Planting position: Slanted at 45° angle or horizontally on flat or ridges at 1 m x 1 m spacing.\n  - Major Disease: Cassava Mosaic Disease (CMD) caused by geminivirus transmitted by whiteflies (Bemisia tabaci); controlled by planting resistant varieties (e.g. Bankyehemaa, Sika bankye).\n• Yam Husbandry (Dioscorea spp.):\n  - Major Species: White yam (D. rotundata), Water yam (D. alata), Yellow yam (D. cayenensis).\n  - Sett Preparation: Seed yams or setts (200–500 g) cut from tubers, treated with wood ash or fungicide to prevent rotting, cured before planting on high mounds/heaps.\n  - Cultural Practices:\n    * Staking: Supporting climbing vines on tall poles to maximize leaf sunlight interception.\n    * Milking (Pricking): Harvesting early ware yams mid-season while leaving roots to regenerate small seed yams.\n  - Pests & Diseases: Yam beetle (Heteroligus meles), yam nematode, anthracnose.",
