            "problem": "A market gardener plants tomatoes on a bed 12 metres long and 1 metre wide, in 2 rows with plants 30 centimetres apart in the row. Each staked plant yields 3 kilograms of fruit. Fruit is packed in 25-kilogram crates that sell for 100 cedis the crate. The seedbed used measures 2 metres by 1 metre. Marks for this question: 20. [20 marks]",
