    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Weed Defined: Any plant growing where it is not desired and causing economic injury or competition to cultivated crops.\n• Botanical Classification:\n  - Grass Weeds (Monocots): Narrow leaves, parallel veins, fibrous roots (e.g. Guinea grass, Imperata cylindrica / spear grass).\n  - Sedge Weeds: Triangular solid stems, 3-ranked leaves (e.g. Cyperus rotundus / nut grass).\n  - Broadleaf Weeds (Dicots): Broad expanded leaves, net venation, taproots (e.g. Chromolaena odorata / Acheampong weed, Euphorbia heterophylla).\n• Harmful Effects: Compete for sunlight, water, nutrients, and space; harbor crop pests and diseases; contaminate grain harvests; increase production costs.\n• Integrated Weed Management (IWM):\n  - Cultural: Crop rotation, high plant density, cover cropping (Mucuna), mulching.\n  - Mechanical: Hand weeding with cutlass/hoe, tractor cultivation.\n  - Chemical: Herbicides (Pre-emergence: applied before weed emergence; Post-emergence: applied on growing weeds; Selective vs. Non-selective e.g. Glyphosate).\n  - Biological: Using specific insects or herbivorous fish to feed exclusively on target weeds.",
