    "keyNotes": "• Classification of Insect Pests by Mouthparts:\n  - Biting & Chewing Insects: Possess strong mandibles; eat leaves, stems, and fruits (e.g. grasshoppers, caterpillars, armyworms, locusts, beetles).\n  - Piercing & Sucking Insects: Possess sharp stylets/proboscis; pierce plant tissues and suck cell sap, transmitting plant viruses and causing leaf curling (e.g. aphids, mealybugs, whiteflies, cotton stainers).\n  - Boring Insects: Larvae or adults drill into stems, pods, seeds, or wood (e.g. maize stem borer, pod borer Maruca, weevils).\n• Integrated Pest Management (IPM):\n  - An ecologically balanced strategy combining multiple pest control tactics to suppress pest populations below the Economic Injury Level (EIL) while minimizing environmental harm.\n  - Components of IPM:\n    * Cultural Control: Crop rotation, trap crops, early planting, sanitation.\n    * Physical / Mechanical: Handpicking caterpillars, pheromone light traps.\n    * Biological Control: Introducing natural predators or parasitoids (e.g. ladybird beetles eating aphids).\n    * Chemical Control: Judicious, targeted application of selective pesticides as a last resort.",
