              "Distance past the threshold: 35 minus 20 = 15 points above the action line. [2 marks]",
              "Cost of control: 3 times 120 = 360 cedis to treat the field. [3 marks]",
              "Grain at risk: 3 times 40 divided by 100 = 1.2 tonnes, worth 1.2 times 600 = 720 cedis. [3 marks]",
              "Return on the decision: 720 minus 360 = 360 cedis saved by spraying at the threshold rather than on the calendar. [2 marks]"
