    "keyNotes": "• The Disease Triangle:\n  - Disease occurs ONLY when three factors coincide: Susceptible Host + Virulent Pathogen + Favorable Environment (moisture, warmth).\n• Major Classes of Plant Pathogens:\n  1. Fungi: Most common crop pathogens; spread by airborne spores, splash rain, contaminated tools.\n     - Examples: Black pod of cocoa, Cercospora leaf spot in groundnut, damping-off in nursery seedlings, blast in rice.\n     - Control: Copper-based fungicides, improved field drainage, wider spacing.\n  2. Bacteria: Enter through natural openings (stomata, lenticels) or wounds.\n     - Examples: Bacterial wilt of tomato (Ralstonia), black rot of cabbage.\n     - Control: Crop rotation with non-host crops, soil sterilization.\n  3. Viruses: Sub-microscopic entities requiring living insect vectors to transmit infection.\n     - Examples: Cassava mosaic disease, cocoa swollen shoot virus, tomato yellow leaf curl virus.\n     - Control: Roguing (uprooting and burning infected plants), vector control, breeding resistant varieties.\n  4. Nematodes (Microscopic roundworms): Attack root systems causing root-knot galls and stunting.",
