            "title": "Measuring how fast blight moves through a plot",
            "problem": "A grower checks 400 tomato plants and finds 60 with early blight after a spell of wet leaves. Ten days later the same 400 plants show 140 infected. The plot was expected to yield 2 tonnes of fruit and the grower takes the loss at the later incidence figure. This is a 15-mark question. [15 marks]",
