            "title": "Sorting a mixed farm by stomach type",
            "problem": "A holding keeps 25 cattle, 40 goats, 12 sheep and 200 layers. Classify the animals by digestive type and find the shares. Marks for this question: 20. [20 marks]",
            "stepByStepSolution": [
              "Stock on the holding: 25 plus 40 plus 12 plus 200 = 277 animals in all. [4 marks]",
              "Ruminants counted together: 25 plus 40 plus 12 = 77 cattle, sheep and goats. [4 marks]",
              "Share that ruminates: 77 divided by 277 times 100 = 27.8 per cent of the stock. [3 marks]",
              "Share that does not: 200 divided by 277 times 100 = 72.2 per cent poultry. [3 marks]",
              "The two classes must close: 27.8 plus 72.2 = 100 per cent of the animals classified. [3 marks]",
              "Cattle, sheep and goats are four-stomached ruminants that can live on forage, while the chicken is simple-stomached and must be given a concentrated ration. [3 marks]"
            ],
