    "keyNotes": "• Nutrient Classes in Animal Diets:\n  - Carbohydrates: Energy source (cereals: maize, sorghum; roughages: grasses).\n  - Proteins: Tissue growth, repair, milk, and egg synthesis (soybean meal, fish meal, cotton seed cake).\n  - Fats & Lipids: Dense energy reserve and fat-soluble vitamin carrier.\n  - Minerals: Macro-minerals (Ca, P for bones and eggshells) and Micro-minerals (Fe, Cu, Zn, Se).\n  - Vitamins: Fat-soluble (A, D, E, K) and Water-soluble (B-complex, C).\n  - Water: Vital for temperature regulation, biochemical reactions, and milk production.\n• Feed Classification:\n  - Roughages: High fiber (> 18% crude fiber), low energy/digestibility (hay, straw, silage, fresh pasture). Essential for ruminants.\n  - Concentrates: Low fiber (< 18% crude fiber), high energy or protein density (maize, wheat bran, fish meal). Essential for monogastrics and high-producing dairy cows.\n• Ration Types:\n  - Maintenance Ration: Minimum feed required to sustain basic bodily functions and constant body weight without gain or loss.\n  - Production Ration: Extra feed provided above maintenance to support milk, meat, wool, egg production, or fetal growth.",
