"examples":       [
          {
            "id": "ex-ani-03-1",
            "title": "Opening a bag of concentrate by component",
            "problem": "A 50-kilogram bag of dairy concentrate is 88 per cent dry matter and 8 per cent ash, and the label gives 18 per cent crude protein, 5 per cent ether extract and 7 per cent crude fibre. Work out what the bag actually contains. Marks for this question: 15. [15 marks]",
            "stepByStepSolution": [
              "Dry matter: 50 times 88 divided by 100 = 44 kilograms of solid feed. [3 marks]",
              "Protein: 50 times 18 divided by 100 = 9 kilograms of crude protein in the bag. [3 marks]",
              "Minerals: 50 times 8 divided by 100 = 4 kilograms of ash. [2 marks]",
              "Organic matter left: 44 minus 4 = 40 kilograms of combustible feed. [3 marks]",
              "Added components: 9 plus 5 plus 7 plus 4 = 25 kilograms named, so 44 minus 25 = 19 kilograms of nitrogen-free extract. [2 marks]",
              "Maize and wheat offal are energy feeds because the nitrogen-free extract is high, while soya bean meal and fish meal are protein feeds supplying the amino acids the animal cannot build. [2 marks]"
            ],
            "keyTakeaway": "A bag is not one substance: 44 kilograms of dry matter carrying 9 kilograms of protein, 19 kilograms of energy and 4 kilograms of mineral."
          },
          {
            "id": "ex-ani-03-2",
            "title": "A square for a 16 per cent ration",
            "problem": "A farmer wants a 100-kilogram mix at 16 per cent crude protein from maize at 9 per cent and soya bean meal at 46 per cent. Use the difference method and then prove the answer. This is a 15-mark question. [15 marks]",
            "stepByStepSolution": [
              "Parts of the protein feed: 16 minus 9 = 7 parts of soya bean meal. [3 marks]",
              "Parts of the energy feed: 46 minus 16 = 30 parts of maize. [2 marks]",
              "Whole mix: 7 plus 30 = 37 parts. [2 marks]",
              "Soya weighed out: 100 times 7 divided by 37 = 18.9 kilograms of soya bean meal. [3 marks]",
              "Maize weighed out: 100 minus 18.9 = 81.1 kilograms of maize. [3 marks]",
              "Proof: 81.1 times 9 divided by 100 = 7.3 and 18.9 times 46 divided by 100 = 8.7, so 7.3 plus 8.7 = 16 per cent as required. [2 marks]"
            ],
            "keyTakeaway": "Two feeds and one target protein give 81.1 kilograms of maize against 18.9 kilograms of soya, and the proof closes at 16 per cent."
          }
        ],
