      "objectives": [
        "Compare inbreeding, crossbreeding, and outbreeding in terms of genetic outcomes",
        "Explain the concept of Heterosis (hybrid vigor) in crossbreeding tropical cattle with exotic breeds",
        "Outline the technical procedures, advantages, and limitations of Artificial Insemination (AI) in Ghana"
      ],
