"examples":       [
          {
            "id": "ex-ani-05-1",
            "title": "What selection is worth in the next generation",
            "problem": "A herd averages 120 kilograms at weaning. Bulls selected as sires average 160 kilograms and the heritability of weaning weight is taken for this exercise as 0.35. From 400 heifers, 15 per cent are kept as replacements. Marks for this question: 15. [15 marks]",
            "stepByStepSolution": [
              "Selection differential: 160 minus 120 = 40 kilograms above the herd average. [3 marks]",
              "Expected response: 40 times 0.35 = 14 kilograms gained in the progeny. [3 marks]",
              "Progeny weaning weight: 120 plus 14 = 134 kilograms. [2 marks]",
              "Replacements drawn: 400 times 15 divided by 100 = 60 heifers retained. [3 marks]",
              "Animals leaving the breeding pool: 400 minus 60 = 340 heifers. [2 marks]",
              "A trait at 0.4 heritability such as fleece weight answers mass selection, while a reproductively low trait near 0.1 must be improved by crossbreeding and management. [2 marks]"
            ],
            "keyTakeaway": "Selection moves the progeny by heritability times the differential: 40 kilograms chosen becomes 14 kilograms inherited."
          },
          {
            "id": "ex-ani-05-2",
            "title": "Insemination priced against a bought bull",
            "problem": "A farmer serves 60 cows by artificial insemination needing 2 services per conception, at 30 cedis a straw. Conception is 65 per cent on the first round. A good bull costs 6,000 cedis plus 1,200 cedis a year to keep. A neighbour instead runs 200 ewes naturally at 1 ram for every 50 ewes. This is a 15-mark question. [15 marks]",
            "stepByStepSolution": [
              "Straws for the herd: 60 times 2 = 120 inseminations. [3 marks]",
              "Cows settled at the first round: 60 times 65 divided by 100 = 39 in calf. [3 marks]",
              "Animals returned for service: 60 minus 39 = 21 cows. [2 marks]",
              "Cost of the programme: 120 times 30 = 3,600 cedis in straws and labour. [3 marks]",
              "Cost of the bull: 6,000 plus 1,200 = 7,200 cedis in the first year, so 7,200 minus 3,600 = 3,600 cedis cheaper by insemination. [2 marks]",
              "Ram power is not free either: 200 divided by 50 = 4 rams for the flock, and every one of them is a living genetic hazard compared with a tested sire. [2 marks]"
            ],
            "keyTakeaway": "Breeding systems are chosen on money and genes: 120 straws at 3,600 cedis against 7,200 cedis for one bull and its keep."
          }
        ],
