    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Swine Characteristics: Monogastric, non-ruminant, omnivorous; high reproductive rate (farrows twice a year with 8–12 piglets per litter), high feed conversion efficiency.\n• Breeds in Ghana:\n  - Large White (Yorkshire): Erect ears, white coat; excellent bacon breed, prolific mother.\n  - Landrace: Drooping ears, long body; outstanding maternal traits.\n  - Ashanti Black Pig (ABP): Indigenous, black, hardy, disease-resistant, heat-tolerant; smaller litter sizes and slower growth.\n• Farrowing & Piglet Management:\n  - Gestation Period: 114 days (3 months, 3 weeks, and 3 days!).\n  - Farrowing Pen: Equipped with guard rails / creep area to prevent the heavy sow from crushing newborn piglets.\n  - Piglet Processing:\n    * Needle teeth clipping (prevents sow teat injury and littermate biting).\n    * Iron Injection (Day 3): Newborn piglets are born with low iron stores and sow milk is iron-deficient; prevents nutritional anemia.\n    * Tail docking and naval cord dipping in iodine.\n    * Creep feeding from 10 days of age.\n• African Swine Fever (ASF): Catastrophic viral disease with up to 100% mortality; no vaccine or cure; requires strict biosecurity and culling.",
