"examples":       [
          {
            "id": "ex-ani-09-1",
            "title": "Counting a sow year in days and weaners",
            "problem": "A unit keeps 12 sows farrowing twice a year and weaning 8 piglets a litter. Gestation is 3 months, 3 weeks and 3 days, and suckling lasts 6 weeks. Marks for this question: 15. [15 marks]",
            "stepByStepSolution": [
              "Gestation in days: 3 months is 90 days, so 90 plus 21 plus 3 = 114 days. [3 marks]",
              "Litters a year: 12 times 2 = 24 litters farrowed. [2 marks]",
              "Piglets weaned: 24 times 8 = 192 weaners. [3 marks]",
              "Output per sow: 192 divided by 12 = 16 weaners to each sow. [2 marks]",
              "Days held by one farrowing: 114 plus 42 = 156 days of pregnancy and suckling. [3 marks]",
              "Two cycles fill the calendar: 156 times 2 = 312 days, leaving 365 minus 312 = 53 days to serve again. [2 marks]"
            ],
            "keyTakeaway": "The three-threes gestation is 114 days, and 156 days per cycle is what limits a sow to about 2 litters a year."
          },
          {
            "id": "ex-ani-09-2",
            "title": "Filling a sty from 30 to 90 kilograms",
            "problem": "Fifty pigs are fed from 30 to 90 kilograms live weight at a feed conversion of 3.5. Ration costs 4 cedis a kilogram and live pork sells at 25 cedis a kilogram. This is a 15-mark question. [15 marks]",
            "stepByStepSolution": [
              "Growth bought per pig: 90 minus 30 = 60 kilograms. [3 marks]",
              "Feed per pig: 60 times 3.5 = 210 kilograms of ration. [3 marks]",
              "Feed for the group: 50 times 210 = 10,500 kilograms. [2 marks]",
              "Feed bill: 10,500 times 4 = 42,000 cedis. [2 marks]",
              "Weight sold: 50 times 90 = 4,500 kilograms, and 4,500 times 25 = 112,500 cedis. [3 marks]",
              "Margin over feed: 112,500 minus 42,000 = 70,500 cedis before housing, labour and veterinary costs. [2 marks]"
            ],
            "keyTakeaway": "A pig is 60 kilograms of gain carrying 210 kilograms of feed, which is the whole argument about ration price."
          }
        ],
