          "content": "• Aquaculture Defined: The controlled farming, cultivation, and harvesting of aquatic organisms (fish, crustaceans, mollusks, aquatic plants) in managed water bodies.\n• Capture Fisheries vs. Culture Fisheries:\n  - Capture Fisheries (Wild Fishing): Catching naturally occurring fish populations from oceans (marine), lakes (Volta Lake), lagoons, and rivers. Currently overexploited due to illegal, unreported, and unregulated (IUU) fishing.\n  - Culture Fisheries (Aquaculture): Encompasses stocking, feeding, protecting, and harvesting fish in human-controlled environments (earthen ponds, cages, concrete tanks).\n• Economic Importance in Ghana:\n  - High Per Capita Consumption: Fish provides over 60% of national animal dietary protein in Ghana.\n  - Livelihoods: Directly and indirectly supports over 3 million people along coastal beaches, Volta lake communities, and inland farms.\n  - Foreign Exchange & Import Substitution: Ghana spends over $200 million annually importing fish; local aquaculture reduces reliance on foreign imports.",
