    "keyNotes": "• External Morphology of Bony Fish (Teleosts):\n  - Fins & Functions:\n    * Caudal fin (tail): Primary propulsion/driving force through water.\n    * Dorsal and Anal fins: Prevent rolling and yawing (stability).\n    * Pectoral and Pelvic fins (paired): Steering, braking, ascending, descending.\n  - Lateral Line: Sensory organ running along the side; detects water pressure waves, currents, vibrations, and nearby predators/prey.\n  - Operculum: Bony protective gill cover that assists in pumping water across respiratory gill filaments.\n• Internal Organ Systems:\n  - Gills: Respiratory organ; rich capillary blood flow where oxygen dissolved in water is absorbed and carbon dioxide excreted through counter-current exchange.\n  - Swim Bladder (Air Bladder): Gas-filled hydrostatic organ enabling the fish to maintain neutral buoyancy at desired water depths without expending swimming energy.\n  - Osmoregulation: Freshwater fish are hyperosmotic to their surrounding water; water continuously enters their bodies by osmosis. They excrete large volumes of dilute urine while absorbing salts through gill chloride cells.",
