            "problem": "A student dissects one tilapia and records the fins, the gill arches and the heart, then notes that the female had been holding fry in her mouth. Take the gestation of the eggs in the buccal cavity as 5 days to hatching and 10 further days of care. Marks for this question: 15. [15 marks]",
            "stepByStepSolution": [
              "Paired fins on the fish: 2 plus 2 = 4 pectoral and pelvic fins. [3 marks]",
              "Unpaired median fins: 1 plus 1 plus 1 = 3 dorsal, anal and caudal fins. [2 marks]",
              "Whole fin complement: 4 plus 3 = 7 fins steering and stabilising the fish. [3 marks]",
              "Gill arches on both sides: 4 times 2 = 8 arches carrying the gill filaments. [3 marks]",
              "The fish heart drives the circuit in 2 main chambers against the 4 of a mammal, so 4 minus 2 = 2 fewer chambers on the blood path. [2 marks]",
              "Maternal care in the mouth: 5 plus 10 = 15 days the tilapia holds her young, which is why hatchery women strip the fry rather than leave them in the pond. [2 marks]"
            ],
            "keyTakeaway": "Structure explains the husbandry: 8 gill arches and a 2-chambered heart make the fish an oxygen-driven animal, and 15 days of mouth brooding makes the fry a harvestable event."
