    "keyNotes": "• Nile Tilapia (Oreochromis niloticus):\n  - Biology: Native cichlid; omnivorous/herbivorous (feeds on phytoplankton, algae, detritus, formulated pellets).\n  - Advantages for Aquaculture: Rapid growth, highly acceptable to Ghanaian consumers, accepts plant-based feeds, disease-resistant.\n  - Aquaculture Challenge: Precocious breeding (matures early at 2–3 months and breeds prolifically, resulting in overcrowded ponds of stunted dwarf fish!).\n  - Solution: All-Male (monosex) Tilapia culture achieved through hormonal sex reversal using 17-alpha methyltestosterone in early fry feed. Males grow 30–40% faster than females!\n• African Sharp-Tooth Catfish (Clarias gariepinus):\n  - Biology: Carnivorous/omnivorous bottom feeder; voracious appetite, extremely rapid growth.\n  - Anatomical Advantage: Possesses an accessory arborescent respiratory organ allowing it to breathe atmospheric air directly from the surface! Can survive in low-oxygen, muddy, stagnant water and high stocking densities.\n  - Aquaculture Challenge: Cannibalism among fingerlings of uneven sizes. Requires regular grading into uniform size groups!",
