    "keyNotes": "• Components of an Earthen Pond:\n  - Dyke / Embankment: Compacted earth walls holding water; 2:1 or 3:1 slope to prevent collapse; crown width of at least 1.5–2.0 meters.\n  - Pond Bottom: Gently sloped (0.5–1%) toward the drainage outlet for complete dewatering.\n  - Inlet & Outlet (The Monk / Standpipe): Inlet screens prevent wild fish entry; monk sluice gates with flashboards control water level and drain bottom stagnant water.\n• Sequential Pond Preparation Steps:\n  1. Dewatering and desilting old sediment.\n  2. Sun-Drying: Cracking pond bottom for 7–14 days to oxidize organic toxins and kill fish parasites.\n  3. Liming: Applying agricultural limestone (CaCO3) at 1,000–2,000 kg/ha to neutralize soil acidity, kill residual parasites, and buffer water.\n  4. Fertilization: Applying poultry manure or cow dung (or NPK) to stimulate primary natural food (phytoplankton and zooplankton bloom).\n  5. Water Inflow: Filling to 1.0–1.2 meters depth; stocking fingerlings when water turns light green (Secchi disc: 30–40 cm).",
