    "keyNotes": "• Fish Seed Production (Hatchery Operations):\n  - Natural spawning in captivity is erratic for African catfish; induced breeding (hypophysation) is mandatory!\n• Induced Breeding Protocol in Catfish:\n  1. Broodstock Selection: Mature, healthy gravid females (distended soft belly, reddish genital papilla) and active males.\n  2. Hormonal Injection: Injecting synthetic hormone (Ovaprim) or pituitary gland extract into female dorsal muscle to trigger egg maturation.\n  3. Latency Period: Waiting 10–12 hours at 26–28°C for eggs to ovulate.\n  4. Stripping & Fertilization: Stripping golden-green eggs into dry plastic bowl; sacrificing male to extract milt (sperm); mixing gently with saline solution and feather.\n  5. Incubation: Spreading fertilized sticky eggs onto kakaban (mesh frames) in flow-through incubation troughs. Eggs hatch within 24–36 hours!\n• Larval Rearing & Nursing:\n  - Yolk Sac Larvae: Feed on internal yolk reserves for 2–3 days.\n  - First Feeding: Decapsulated Artemia (brine shrimp nauplii) or zooplankton. Transition to high-protein starter micro-pellets (> 45% CP).",
