    "keyNotes": "• Managing Water Quality Crisis:\n  - Dissolved Oxygen Depletion Causes: Over-feeding (uneaten pellets rotting on pond bottom), dense algae blooms consuming oxygen at night, cloudy windless days, sudden die-off of phytoplankton (\"algae bloom crash\").\n  - Behavioral Signs: Fish piping (gasping for air at the water surface with open mouths), sluggish swimming, refusal to feed, fish concentrated near inlets.\n• Aeration Mechanisms:\n  - Emergency measures: Flushing fresh oxygenated water into pond, mechanical splashing.\n  - Continuous Aeration: Paddlewheel aerators, aspirators, diffused bottom aerator bubbling oxygen.\n• Algae Bloom Management:\n  - Phytoplankton is beneficial (oxygen and natural food), but excessive blooms (pea-soup green, Secchi depth < 20 cm) trigger night suffocation and daytime supersaturation.\n  - Remedy: Controlled water exchange (discharging bottom water, adding fresh water) and reducing feed volume.\n• Maintenance: Cutting weeds on dykes, inspecting screening meshes, clearing silt from drainage monks.",
