            "problem": "A farmer treats a 2-cubic-metre holding tank with common salt at 30 grams a litre for a short bath. The tank carries 400 fish, salt costs 2 cedis a kilogram, and the class exercise repeats the bath weekly for 4 weeks. Marks for this question: 15. [15 marks]",
