            "stepByStepSolution": [
              "Weight lost in the kiln: 300 times 25 divided by 100 = 75 kilograms, leaving 300 minus 75 = 225 kilograms of smoked fish. [3 marks]",
              "What the raw catch was worth: 300 times 8 = 2,400 cedis. [3 marks]",
              "What the smoked product fetches: 225 times 14 = 3,150 cedis. [3 marks]",
              "Gain from the smoke: 3,150 minus 2,400 = 750 cedis. [2 marks]",
              "Gain after the fuel: 750 minus 150 = 600 cedis. [2 marks]",
              "Smoking keeps the fish for weeks because the heat removes the moisture the spoilage organisms need, while over-smoking leaves a brittle, second-grade product. [2 marks]"
            ],
