          "content": "• Commercial Timber Species in Ghana:\n  - High-Value Hardwoods (Heavy, durable, termite-resistant):\n    * Odum (Milicia excelsa): Premier heavy construction and furniture wood; extremely durable.\n    * African Mahogany (Khaya ivorensis): Highly prized reddish-brown decorative cabinet and veneer timber.\n    * Sapele (Entandrophragma cylindricum): Aromatic cedar-like wood for high-grade cabinetry.\n    * Teak (Tectona grandis): Exotic plantation hardwood; highly rot-resistant; electric transmission poles.\n  - Light Commercial Woods: Wawa (Triplochiton scleroxylon): Soft white wood used for plywood, molding, and disposable crates.\n• Non-Timber Forest Products (NTFPs):\n  - Forest goods other than timber harvested from forests:\n    * Medicinal plants: Bark of Alstonia boonei (malaria), Griffonia simplicifolia seeds, Voacanga.\n    * Edible resources: Wild mushrooms, snails, honey, bushmeat (duikers, grasscutters).\n    * Fibers & Craft materials: Rattan cane, bamboo, chewsticks (Garcinia kola), sponge.\n• Economic Contribution: Generates export revenue through the Timber Industry Development Division (TIDD) of the Forestry Commission.",
