              "Share of the transition: 10,000 divided by 40,000 times 100 = 25 per cent. [2 marks]",
              "Share of woodland: 6,000 divided by 40,000 times 100 = 15 per cent. [2 marks]",
              "Share of the fringes: 2,000 divided by 40,000 times 100 = 5 per cent. [2 marks]",
              "Forest side of the line: 55 plus 25 = 80 per cent of the district is forest or its transition, and it is the falling rainfall and the lengthening dry season that place the boundary. [3 marks]"
