            "stepByStepSolution": [
              "Cedro in the yard: 12 times 0.9 = 10.8 cubic metres of logs. [3 marks]",
              "Wawa in the yard: 8 times 1.4 = 11.2 cubic metres. [3 marks]",
              "Whole intake: 10.8 plus 11.2 = 22 cubic metres sawn. [2 marks]",
              "Boards from cedro: 10.8 times 45 divided by 100 = 4.86 cubic metres. [3 marks]",
              "Boards from wawa: 11.2 times 55 divided by 100 = 6.16 cubic metres. [2 marks]",
              "Residue to the burner or the mill: 4.86 plus 6.16 = 11.02 cubic metres of boards, so 22 minus 11.02 = 10.98 cubic metres of offal and sawdust, and cedro as a broad-leaved hardwood is grouped on wood structure, not on how hard it feels. [2 marks]"
            ],
            "keyTakeaway": "Hardwood against softwood is an anatomical statement: 22 cubic metres of logs leaves only 11.02 cubic metres of boards, and the rest is residue."
