    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Forest Nursery Site Selection: Permanent reliable water source, central location to planting site, good road access, gentle slope (well-drained sandy loam).\n• Seed Dormancy & Pre-Treatment:\n  - Many forest seeds possess hard impermeable seed coats (e.g. Teak, Cassia) or physiological embryo dormancy.\n  - Breaking Dormancy:\n    * Mechanical Scarification: Nicking, filing, or abrading the seed coat to allow water penetration.\n    * Thermal / Hot Water Treatment: Soaking seeds in boiling water allowed to cool for 24 hours.\n    * Chemical Scarification: Soaking in concentrated sulfuric acid for a few minutes.\n    * Stratification: Chilling moist seeds at low temperatures to break embryo dormancy.\n• Nursery Cultural Practices:\n  - Potting: Filling perforated polythene bags with a fertile potting mix (3 parts topsoil, 2 parts compost, 1 part sand).\n  - Shading: Providing 50–70% shade using palm fronds on overhead trellises.\n  - Pricking Out: Transferring germinated seedlings from seedbeds to individual polypots.\n  - Hardening Off: Gradually removing shade and reducing watering 3–4 weeks prior to field planting to acclimatize seedlings to harsh open field conditions.",
