            "problem": "A survey of a 300-hectare compartment finds 2,400 trees above the minimum cutting diameter. The working plan permits the removal of 40 per cent of them, each yielding 0.8 cubic metre of logs at 300 cedis, and the mill recovers 45 per cent of the log volume as boards. Marks for this question: 15. [15 marks]",
