    "keyNotes": "• Agroforestry Defined: A dynamic, ecologically based natural resource management system that deliberately integrates woody perennials (trees, shrubs) on the same land management unit with agricultural crops and/or animals.\n• Three Core Classifications:\n  1. Agrosilvicultural Systems: Trees + Agricultural crops (e.g. Alley cropping, shade trees in cocoa, boundary planting).\n  2. Silvopastoral Systems: Trees + Pasture / Livestock grazing (e.g. cattle grazing under coconut or cashew plantations, fodder banks).\n  3. Agrosilvopastoral Systems: Trees + Crops + Animals (e.g. Multistorey compound home gardens).\n• Specific Agroforestry Practices:\n  - Alley Cropping (Hedgerow intercropping): Growing food crops in alleys between hedgerows of nitrogen-fixing trees (e.g. Leucaena leucocephala, Gliricidia sepium); pruned prunings provide rich green mulch.\n  - Shelterbelts / Windbreaks: Linear belts of trees planted perpendicular to prevailing winds to protect crops from wind damage and reduce soil erosion.\n  - Fodder Banks: Densely planted protein-rich leguminous browse trees harvested to feed ruminants during dry seasons.",
