    "keyNotes": "• Deforestation in Ghana: The permanent destruction and clearance of natural forest cover for other land uses. Ghana has lost over 80% of its original high forest cover since 1900.\n• Primary Drivers of Deforestation:\n  - Agricultural Expansion: Slash-and-burn shifting cultivation clearing virgin forest canopies for cocoa, oil palm, and food crops.\n  - Illegal Chain-Saw Milling: Unlicensed logging targeting high-value timber species (Rosewood, Odum, Mahogany), causing canopy collapse.\n  - Illegal Surface Mining (\"Galamsey\"): Digging massive open pits in forest reserves, stripping topsoil, and polluting forest watercourses with mercury and cyanide.\n  - Wildfires: Uncontrolled bushfires during the dry Harmattan season, started by poachers, cigarette butts, and slash-and-burn farming, destroying forest fringes.\n  - Fuelwood & Charcoal Production: Heavy pressure on savanna woodlands for domestic cooking energy.\n• Ecological Consequences:\n  - Severe soil erosion, loss of topsoil fertility, and siltation of rivers.\n  - Accelerated climate change due to loss of terrestrial carbon sinks.\n  - Destruction of wildlife habitats and extinction of rare flora and fauna.",
