              "Shortfall to be grown: 7,155,000 minus 5,000,000 = 2,155,000 hectares. [3 marks]",
              "Years of restoration work: 2,155,000 divided by 20,000 = 107.75 years at that pace. [2 marks]",
              "Compartments to plan: 1,600,000 divided by 500 = 3,200 compartments of 500 hectares to bring under a working plan. [2 marks]",
