              "Value of the pool: 135,000 times 15 = 2,025,000 cedis of credits. [3 marks]",
              "Carbon released by cutting: 135,000 times 4 divided by 100 = 5,400 tonnes. [2 marks]",
              "Value released with it: 5,400 times 15 = 81,000 cedis. [2 marks]",
              "Credit left to sell: 2,025,000 minus 81,000 = 1,944,000 cedis, and 1,944,000 times 70 divided by 100 = 1,360,800 cedis to the community. [3 marks]",
